def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # Maps id to (side, price, arrival_time, index_in_book)
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, _, book_index = order_map[order_id]
                if side == 'buy':
                    if book_index < len(buy_book) and buy_book[book_index][2] == order_id:
                        buy_book[book_index] = (price, arrival_time, order_id, 0)
                else:
                    if book_index < len(sell_book) and sell_book[book_index][2] == order_id:
                        sell_book[book_index] = (price, arrival_time, order_id, 0)
                del order_map[order_id]

