                    sell_book[i] = (sell_price, arr_time, sell_id, sell_qty - trade_qty)
                    if sell_id in order_map:
                        del order_map[sell_id]

                if remaining_qty > 0:
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('buy', price, arrival_time, len(buy_book) - 1)
